{
  "title": "Slow morning, sea breeze afternoon",
  "summary": "A gentle day that starts late, lingers by the water, and ends with a quiet evening in the same corner of the city.",
  "stops": [
    {
      "poi_id": "p42",
      "kind": "meal",
      "must_do_id": null,
      "note": "A late breakfast of mì Quảng (turmeric noodles with pork, shrimp and a sesame cracker) to start the day without rushing.",
      "must_do_id": null
    },
    {
      "poi_id": "p36",
      "kind": "activity",
      "must_do_id": null,
      "note": "East Sea Park gives us an easy stroll by the water, perfect for a slow morning with no early alarm.",
      "must_do_id": null
    },
    {
      "poi_id": "p81",
      "kind": "activity",
      "must_do_id": null,
      "note": "A coconut cream break, because a lazy day still deserves a sweet little pause.",
      "must_do_id": null
    },
    {
      "poi_id": "p82",
      "kind": "activity",
      "must_do_id": null,
      "note": "We time this beach stop for the sunset, when the sky does all the work and we just watch.",
      "must_do_id": null
    },
    {
      "poi_id": "p53",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner at Ốc Cười, a street-food spot that keeps the evening local and unhurried.",
      "must_do_id": null
    },
    {
      "poi_id": "p31",
      "kind": "activity",
      "must_do_id": null,
      "note": "Apocalyse Now beach club for a soft after-dark finish, still by the sea and still very much on our own clock.",
      "must_do_id": null
    }
  ]
}
